using YotsubaShader.Language;
using YotsubaShader.GlslSyntax;
using YotsubaShader.GlslSyntax.Types;
using YotsubaShader.GlslSyntax.Resources;
using static YotsubaShader.GlslSyntax.Methods.Math;
using static YotsubaShader.GlslSyntax.Methods.Intrinsic;

public struct Globals
{
    public float Time;
    public vec2 Resolution;
}

public struct VertexOutput
{
    [gl_Position]
    public vec4 Position;
}

public class Aurora
{
    [uniform, layout(0, 0)]
    public Globals Params;

    // One triangle that covers the whole screen, built from the vertex index.
    [ShaderStage(Stage.Vertex)]
    public VertexOutput Vertex([gl_VertexIndex] uint id)
    {
        vec4 position;
        position.X = ((id << 1) & 2) * 2.0f - 1.0f;
        position.Y = (id & 2) * 2.0f - 1.0f;
        position.Z = 0.0f;
        position.W = 1.0f;

        VertexOutput output;
        output.Position = position;
        return output;
    }

    vec3 Rgb(float r, float g, float b)
    {
        vec3 color;
        color.X = r;
        color.Y = g;
        color.Z = b;
        return color;
    }

    float Hash(float x, float y)
    {
        return fract(sin(x * 127.1f + y * 311.7f) * 43758.5453f);
    }

    float Noise(float x, float y)
    {
        float cellX = floor(x);
        float cellY = floor(y);
        float fx = x - cellX;
        float fy = y - cellY;
        float ux = fx * fx * (3.0f - 2.0f * fx);
        float uy = fy * fy * (3.0f - 2.0f * fy);

        float a = Hash(cellX, cellY);
        float b = Hash(cellX + 1.0f, cellY);
        float c = Hash(cellX, cellY + 1.0f);
        float d = Hash(cellX + 1.0f, cellY + 1.0f);
        return mix(mix(a, b, ux), mix(c, d, ux), uy);
    }

    // Layers of noise, each one finer and fainter than the last.
    float Fbm(float x, float y)
    {
        float sum = 0.0f;
        float amplitude = 0.5f;
        float qx = x;
        float qy = y;
        for (int i = 0; i < 5; i++)
        {
            sum += amplitude * Noise(qx, qy);
            qx = qx * 2.03f + 17.3f;
            qy = qy * 2.03f + 9.1f;
            amplitude *= 0.5f;
        }
        return sum;
    }

    // Night blue, violet, pink, then a warm peach at the brightest folds.
    vec3 Ramp(float t)
    {
        vec3 color = Rgb(0.02f, 0.03f, 0.12f);
        color = mix(color, Rgb(0.08f, 0.22f, 0.85f), smoothstep(0.00f, 0.30f, t));
        color = mix(color, Rgb(0.58f, 0.26f, 0.95f), smoothstep(0.30f, 0.55f, t));
        color = mix(color, Rgb(1.00f, 0.36f, 0.60f), smoothstep(0.55f, 0.78f, t));
        color = mix(color, Rgb(1.00f, 0.78f, 0.46f), smoothstep(0.78f, 1.00f, t));
        return color;
    }

    [ShaderStage(Stage.Fragment)]
    public vec4 Fragment([gl_FragCoord] vec4 fragCoord)
    {
        float aspect = Params.Resolution.X / Params.Resolution.Y;
        float x = (fragCoord.X / Params.Resolution.X - 0.5f) * aspect * 1.5f;
        float y = (fragCoord.Y / Params.Resolution.Y - 0.5f) * 1.5f;
        float t = Params.Time * 0.10f;

        // Warp the coordinates with noise twice to get slow, silky folds.
        float qx = Fbm(x, y + t);
        float qy = Fbm(x + 5.2f, y + 1.3f - t);
        float rx = Fbm(x + qx * 2.2f + 1.7f, y + qy * 2.2f + 9.2f + t);
        float ry = Fbm(x + qx * 2.2f + 8.3f, y + qy * 2.2f + 2.8f - t);
        float field = Fbm(x + rx * 1.6f, y + ry * 1.6f);

        float level = clamp((field - 0.12f) * 2.3f + (rx - 0.5f) * 0.4f, 0.0f, 1.0f);
        vec3 color = Ramp(level);

        // Soft vignette so the edges fall into the dark.
        vec2 centered;
        centered.X = x;
        centered.Y = y;
        float vignette = 1.0f - smoothstep(0.6f, 1.7f, length(centered) * 0.8f);
        float shade = 0.45f + 0.55f * vignette;

        vec4 result;
        result.X = color.X * shade;
        result.Y = color.Y * shade;
        result.Z = color.Z * shade;
        result.W = 1.0f;
        return result;
    }
}

using YotsubaShader.Language;
using YotsubaShader.GlslSyntax;
using YotsubaShader.GlslSyntax.Types;
using YotsubaShader.GlslSyntax.Resources;
using YotsubaShader.GlslSyntax.Resources.Types;
using static YotsubaShader.GlslSyntax.Methods.Math;
using static YotsubaShader.GlslSyntax.Methods.Intrinsic;

public struct Globals
{
    public float Time;
    public vec2 Resolution;
    public vec4 Mouse;
}

public struct VertexOutput
{
    [gl_Position]
    public vec4 Position;
}

public class Bricks
{
    [uniform, layout(0, 0)]
    public Globals Params;

    // Two images: the colour of the wall and a height map with its relief.
    // Red Brick by Poly Haven (polyhaven.com/a/red_brick), CC0.
    [uniform, layout(0, 1)]
    public sampler2D Albedo;

    [uniform, layout(0, 2)]
    public sampler2D Height;

    [ShaderStage(Stage.Vertex)]
    public VertexOutput Vertex([gl_VertexIndex] uint id)
    {
        vec4 position;
        position.X = ((id << 1) & 2) * 2.0f - 1.0f;
        position.Y = (id & 2) * 2.0f - 1.0f;
        position.Z = 0.0f;
        position.W = 1.0f;

        VertexOutput output;
        output.Position = position;
        return output;
    }

    vec3 Rgb(float r, float g, float b)
    {
        vec3 color;
        color.X = r;
        color.Y = g;
        color.Z = b;
        return color;
    }

    vec2 Uv(float u, float v)
    {
        vec2 uv;
        uv.X = u;
        uv.Y = v;
        return uv;
    }

    float HeightAt(float u, float v)
    {
        return texture(Height, Uv(u, v)).X;
    }

    vec3 ColorAt(float u, float v)
    {
        vec4 texel = texture(Albedo, Uv(u, v));
        return Rgb(texel.X, texel.Y, texel.Z);
    }

    // One lamp at (lampX, lampY), a little in front of the wall.
    vec3 Lamp(float x, float y, vec3 normal, vec3 albedo, float lampX, float lampY, vec3 tint, float power)
    {
        float toX = lampX - x;
        float toY = lampY - y;
        float toZ = 0.30f;
        float away = sqrt(toX * toX + toY * toY + toZ * toZ);
        vec3 l = Rgb(toX / away, toY / away, toZ / away);
        float falloff = 1.0f / (1.0f + 2.2f * away * away);

        vec3 halfway = normalize(Rgb(l.X, l.Y, l.Z + 1.0f));
        float diffuse = clamp(dot(normal, l), 0.0f, 1.0f) * falloff * power;
        float specular = pow(clamp(dot(normal, halfway), 0.0f, 1.0f), 30.0f) * falloff * 0.5f * power;

        // A small glow around the lamp itself.
        float glow = 0.004f / (away * away * 0.25f + 0.004f) * 0.05f;
        float shine = specular + glow;
        return Rgb(
            tint.X * (albedo.X * diffuse + shine),
            tint.Y * (albedo.Y * diffuse + shine),
            tint.Z * (albedo.Z * diffuse + shine));
    }

    [ShaderStage(Stage.Fragment)]
    public vec4 Fragment([gl_FragCoord] vec4 fragCoord)
    {
        float aspect = Params.Resolution.X / Params.Resolution.Y;
        float x = fragCoord.X / Params.Resolution.X * aspect;
        float y = fragCoord.Y / Params.Resolution.Y;
        float u = x * 1.15f;
        float v = y * 1.15f;

        // The slope of the height map gives the direction each brick face leans towards.
        float e = 0.0015f;
        float slopeX = HeightAt(u + e, v) - HeightAt(u - e, v);
        float slopeY = HeightAt(u, v + e) - HeightAt(u, v - e);
        vec3 normal = normalize(Rgb(-slopeX * 14.0f, -slopeY * 14.0f, 1.0f));

        // A warm light circles the wall. Press and drag inside the preview to move it yourself.
        float t = Params.Time * 0.6f;
        float lampX = (0.5f + 0.38f * cos(t)) * aspect;
        float lampY = 0.5f + 0.34f * sin(t * 1.3f);
        if (Params.Mouse.Z > 0.5f)
        {
            lampX = Params.Mouse.X / Params.Resolution.X * aspect;
            lampY = Params.Mouse.Y / Params.Resolution.Y;
        }

        vec3 albedo = ColorAt(u, v);

        // The warm lamp, and a cool one on the opposite side of the wall.
        vec3 warm = Lamp(x, y, normal, albedo, lampX, lampY, Rgb(1.00f, 0.74f, 0.42f), 2.6f);
        vec3 cool = Lamp(x, y, normal, albedo, aspect - lampX, 1.0f - lampY, Rgb(0.28f, 0.50f, 1.00f), 1.3f);

        vec4 result;
        result.X = albedo.X * 0.05f + warm.X + cool.X;
        result.Y = albedo.Y * 0.07f + warm.Y + cool.Y;
        result.Z = albedo.Z * 0.13f + warm.Z + cool.Z;
        result.W = 1.0f;
        return result;
    }
}

using YotsubaShader.Language;
using YotsubaShader.GlslSyntax;
using YotsubaShader.GlslSyntax.Types;
using YotsubaShader.GlslSyntax.Resources;
using static YotsubaShader.GlslSyntax.Methods.Math;
using static YotsubaShader.GlslSyntax.Methods.Intrinsic;

public struct Globals
{
    public float Time;
    public vec2 Resolution;
}

public struct VertexOutput
{
    [gl_Position]
    public vec4 Position;
}

public class Fractal
{
    [uniform, layout(0, 0)]
    public Globals Params;

    [ShaderStage(Stage.Vertex)]
    public VertexOutput Vertex([gl_VertexIndex] uint id)
    {
        vec4 position;
        position.X = ((id << 1) & 2) * 2.0f - 1.0f;
        position.Y = (id & 2) * 2.0f - 1.0f;
        position.Z = 0.0f;
        position.W = 1.0f;

        VertexOutput output;
        output.Position = position;
        return output;
    }

    vec3 Palette(float t)
    {
        vec3 color;
        color.X = 0.5f + 0.5f * cos(6.28318f * (t + 0.00f));
        color.Y = 0.5f + 0.5f * cos(6.28318f * (t + 0.10f));
        color.Z = 0.5f + 0.5f * cos(6.28318f * (t + 0.20f));
        return color;
    }

    [ShaderStage(Stage.Fragment)]
    public vec4 Fragment([gl_FragCoord] vec4 fragCoord)
    {
        float aspect = Params.Resolution.X / Params.Resolution.Y;
        float u = fragCoord.X / Params.Resolution.X;
        float v = fragCoord.Y / Params.Resolution.Y;

        // Zoom in towards the seahorse valley and back out, forever.
        float breathe = 0.5f - 0.5f * cos(Params.Time * 0.22f);
        float scale = 2.6f * exp(-5.2f * breathe);
        float cx = -0.743644f + (u - 0.5f) * aspect * scale;
        float cy = 0.131826f + (v - 0.5f) * scale;

        float x = 0.0f;
        float y = 0.0f;
        float steps = 0.0f;
        float trap = 1000.0f;
        bool escaped = false;
        for (int i = 0; i < 180; i++)
        {
            float nx = x * x - y * y + cx;
            y = 2.0f * x * y + cy;
            x = nx;
            if (x * x + y * y > 256.0f)
            {
                escaped = true;
                break;
            }
            // Remember how close the orbit came to a small circle: it colours the inside of the set.
            trap = min(trap, abs(x * x + y * y - 0.18f));
            steps += 1.0f;
        }

        vec3 color = Palette(sqrt(trap) * 1.1f + 0.62f);
        float shade = 0.5f;
        if (escaped)
        {
            // Smooth iteration count: no visible bands between the steps.
            float smoothSteps = steps - log2(log2(x * x + y * y)) + 4.0f;
            color = Palette(smoothSteps * 0.035f + Params.Time * 0.03f + 0.55f);
            shade = 0.35f + 0.65f * smoothstep(0.0f, 14.0f, smoothSteps);
        }

        vec4 result;
        result.X = color.X * shade;
        result.Y = color.Y * shade;
        result.Z = color.Z * shade;
        result.W = 1.0f;
        return result;
    }
}

using System;
using YotsubaShader.Language;
using YotsubaShader.GlslSyntax;
using YotsubaShader.GlslSyntax.Types;
using YotsubaShader.GlslSyntax.Resources;

// ------------------------------------------------------------------ interface

public struct Globals
{
    public float Time;
    public vec2 Resolution;
    public vec4 Mouse;
}

public struct VertexOutput
{
    [gl_Position]
    public vec4 Position;
}

public class Mandelbulb
{
    [uniform, layout(0, 0)]
    public Globals Params;

    // One triangle that covers the whole screen, built from the vertex index.
    [ShaderStage(Stage.Vertex)]
    public VertexOutput Vertex([gl_VertexIndex] uint id)
    {
        float x = (id << 1) & 2;
        float y = id & 2;

        VertexOutput output;
        output.Position = new vec4(x * 2.0f - 1.0f, y * 2.0f - 1.0f, 0.0f, 1.0f);
        return output;
    }

    // ------------------------------------------------------------------ helpers

    static float Saturate(float x) => Math.Clamp(x, 0.0f, 1.0f);
    static float Frac(float x) => x - MathF.Floor(x);
    static float Dot(vec3 a, vec3 b) => a.X * b.X + a.Y * b.Y + a.Z * b.Z;
    static float Length(vec3 a) => MathF.Sqrt(Dot(a, a));
    static vec3 Normalize(vec3 a) => a * (1.0f / Length(a));
    static vec3 Mix(vec3 a, vec3 b, float t) => a + (b - a) * t;

    static vec3 Cross(vec3 a, vec3 b)
    {
        return new vec3(a.Y * b.Z - a.Z * b.Y, a.Z * b.X - a.X * b.Z, a.X * b.Y - a.Y * b.X);
    }

    static float Smoothstep(float a, float b, float x)
    {
        float t = Saturate((x - a) / (b - a));
        return t * t * (3.0f - 2.0f * t);
    }

    // Every colour of the rainbow, one full turn for each unit of t.
    static vec3 Rainbow(float t)
    {
        return new vec3(
            0.5f + 0.5f * MathF.Cos(6.28318f * t),
            0.5f + 0.5f * MathF.Cos(6.28318f * (t + 0.33f)),
            0.5f + 0.5f * MathF.Cos(6.28318f * (t + 0.67f)));
    }

    // ------------------------------------------------------------------ the bulb

    // The exponent breathes between 4 and 10, so the shape keeps melting into a new one.
    float Power()
    {
        return 7.0f + 3.0f * MathF.Sin(Params.Time * 0.23f);
    }

    // The whole bulb turns on two axes at once.
    vec3 Spin(vec3 p)
    {
        float a = Params.Time * 0.17f;
        float b = Params.Time * 0.11f;
        vec3 q = new vec3(p.X * MathF.Cos(a) - p.Z * MathF.Sin(a), p.Y, p.X * MathF.Sin(a) + p.Z * MathF.Cos(a));
        return new vec3(q.X, q.Y * MathF.Cos(b) - q.Z * MathF.Sin(b), q.Y * MathF.Sin(b) + q.Z * MathF.Cos(b));
    }

    // Distance from a point to the surface: z = z^power + c in spherical coordinates, repeated.
    float Bulb(vec3 position)
    {
        vec3 c = Spin(position);
        float power = Power();
        vec3 z = c;
        float dr = 1.0f;
        float r = 0.0f;
        for (int i = 0; i < 8; i++)
        {
            r = Length(z);
            if (r > 2.0f) break;
            float theta = MathF.Acos(Math.Clamp(z.Y / r, -1.0f, 1.0f)) * power;
            float phi = MathF.Atan2(z.Z, z.X) * power;
            float zr = MathF.Pow(r, power);
            dr = zr / r * power * dr + 1.0f;
            z = new vec3(MathF.Sin(theta) * MathF.Cos(phi), MathF.Cos(theta), MathF.Sin(theta) * MathF.Sin(phi)) * zr + c;
        }
        return 0.5f * MathF.Log(r) * r / dr;
    }

    // Where the orbit of a surface point went: closest to the centre, closest to the plane y = 0, and how long it lasted.
    vec3 Trap(vec3 position)
    {
        vec3 c = Spin(position);
        float power = Power();
        vec3 z = c;
        float centre = 100.0f;
        float plane = 100.0f;
        float steps = 0.0f;
        for (int i = 0; i < 8; i++)
        {
            float r = Length(z);
            if (r > 2.0f) break;
            centre = MathF.Min(centre, r);
            plane = MathF.Min(plane, MathF.Abs(z.Y));
            steps += 1.0f;
            float theta = MathF.Acos(Math.Clamp(z.Y / r, -1.0f, 1.0f)) * power;
            float phi = MathF.Atan2(z.Z, z.X) * power;
            float zr = MathF.Pow(r, power);
            z = new vec3(MathF.Sin(theta) * MathF.Cos(phi), MathF.Cos(theta), MathF.Sin(theta) * MathF.Sin(phi)) * zr + c;
        }
        return new vec3(centre, plane, steps / 8.0f);
    }

    vec3 Normal(vec3 p)
    {
        float e = 0.0008f;
        vec3 a = new vec3(1.0f, -1.0f, -1.0f);
        vec3 b = new vec3(-1.0f, -1.0f, 1.0f);
        vec3 c = new vec3(-1.0f, 1.0f, -1.0f);
        vec3 d = new vec3(1.0f, 1.0f, 1.0f);
        return Normalize(a * Bulb(p + a * e) + b * Bulb(p + b * e) + c * Bulb(p + c * e) + d * Bulb(p + d * e));
    }

    // Cracks and folds receive less light than the open surface.
    float Occlusion(vec3 p, vec3 n)
    {
        float hidden = 0.0f;
        float weight = 1.0f;
        for (int i = 0; i < 5; i++)
        {
            float h = 0.01f + 0.03f * i;
            hidden += (h - Bulb(p + n * h)) * weight;
            weight *= 0.7f;
        }
        return Saturate(1.0f - 3.0f * hidden);
    }

    // ------------------------------------------------------------------ space

    vec3 Space(vec3 direction)
    {
        float t = Params.Time;
        vec3 color = Mix(new vec3(0.03f, 0.0f, 0.06f), new vec3(0.0f, 0.02f, 0.08f), direction.Y * 0.5f + 0.5f);

        // A slow nebula that changes colour with time.
        float swirl = MathF.Sin(direction.X * 3.0f + t * 0.3f) * MathF.Sin(direction.Y * 4.0f - t * 0.2f) * MathF.Sin(direction.Z * 5.0f + t * 0.25f);
        color = color + Rainbow(swirl * 0.4f + t * 0.03f) * (0.12f * swirl * swirl);

        // Stars: one random number per small cell of the sky.
        float seed = Frac(MathF.Sin(MathF.Floor(direction.X * 180.0f) * 12.9898f + MathF.Floor(direction.Y * 180.0f) * 78.233f + MathF.Floor(direction.Z * 180.0f) * 37.719f) * 43758.5453f);
        float star = Smoothstep(0.996f, 1.0f, seed) * (0.6f + 0.4f * MathF.Sin(t * 3.0f + seed * 90.0f));
        return color + new vec3(1.0f, 0.92f, 0.96f) * (star * 1.6f);
    }

    // ------------------------------------------------------------------ the picture

    [ShaderStage(Stage.Fragment)]
    public vec4 Fragment([gl_FragCoord] vec4 fragCoord)
    {
        float t = Params.Time;
        float x = (fragCoord.X * 2.0f - Params.Resolution.X) / Params.Resolution.Y;
        float y = (fragCoord.Y * 2.0f - Params.Resolution.Y) / Params.Resolution.Y;

        // The camera circles the bulb. Press and drag inside the preview to turn it yourself.
        float yaw = t * 0.15f;
        float pitch = 0.3f + 0.25f * MathF.Sin(t * 0.1f);
        if (Params.Mouse.Z > 0.5f)
        {
            yaw = (Params.Mouse.X / Params.Resolution.X - 0.5f) * 6.2832f;
            pitch = Math.Clamp((Params.Mouse.Y / Params.Resolution.Y - 0.5f) * 3.0f, -1.3f, 1.3f);
        }
        float away = 2.5f + 0.35f * MathF.Sin(t * 0.13f);
        vec3 origin = new vec3(MathF.Sin(yaw) * MathF.Cos(pitch), MathF.Sin(pitch), MathF.Cos(yaw) * MathF.Cos(pitch)) * away;
        vec3 forward = Normalize(origin * -1.0f);
        vec3 right = Normalize(Cross(forward, new vec3(0.0f, 1.0f, 0.0f)));
        vec3 up = Cross(right, forward);
        vec3 direction = Normalize(forward * 1.8f + right * x + up * y);

        // Only rays that enter the sphere around the bulb need to march.
        float travelled = 0.0f;
        float glow = 0.0f;
        bool hit = false;
        float b = Dot(origin, direction);
        float inside = b * b - Dot(origin, origin) + 2.25f;
        if (inside > 0.0f)
        {
            travelled = MathF.Max(0.0f, -b - MathF.Sqrt(inside));
            float exit = -b + MathF.Sqrt(inside);
            for (int i = 0; i < 110; i++)
            {
                float d = Bulb(origin + direction * travelled);
                // Every near miss adds a little light: that is the halo around the edges.
                glow += 1.0f / (1.0f + d * d * 2500.0f);
                if (d < 0.0004f * travelled)
                {
                    hit = true;
                    break;
                }
                travelled += d * 0.9f;
                if (travelled > exit) break;
            }
        }

        vec3 color = Space(direction);
        if (hit)
        {
            vec3 p = origin + direction * travelled;
            vec3 n = Normal(p);
            vec3 trap = Trap(p);
            vec3 albedo = Rainbow(trap.X * 3.0f + trap.Y * 5.0f + trap.Z * 0.7f + t * 0.06f);
            albedo = Mix(albedo, new vec3(1.0f, 0.95f, 0.9f), Saturate(1.0f - trap.Y * 12.0f) * 0.5f);

            // A white key light from above and a magenta one from below.
            vec3 light = Normalize(new vec3(0.6f, 0.8f, -0.4f));
            vec3 under = Normalize(new vec3(-0.5f, -0.7f, 0.5f));
            float diffuse = Saturate(Dot(n, light));
            float bounce = Saturate(Dot(n, under));
            float specular = MathF.Pow(Saturate(Dot(n, Normalize(light - direction))), 40.0f);
            float fresnel = MathF.Pow(1.0f - Saturate(-Dot(n, direction)), 3.0f);
            float occlusion = Occlusion(p, n);

            color = albedo * ((diffuse * 1.5f + 0.08f) * occlusion)
                + new vec3(1.0f, 0.15f, 0.65f) * (bounce * 0.6f * occlusion)
                + new vec3(1.0f, 1.0f, 1.0f) * (specular * 0.9f * occlusion)
                + Rainbow(fresnel * 1.5f + t * 0.1f) * (fresnel * 0.8f);
            glow *= 0.35f;
        }
        color = color + Rainbow(t * 0.05f + 0.6f) * (glow * 0.016f);

        // Darker corners, a soft tone curve, then gamma.
        color = color * (1.0f - 0.18f * (x * x + y * y));
        return new vec4(
            MathF.Pow(color.X / (1.0f + color.X), 0.4545f),
            MathF.Pow(color.Y / (1.0f + color.Y), 0.4545f),
            MathF.Pow(color.Z / (1.0f + color.Z), 0.4545f),
            1.0f);
    }
}

using YotsubaShader.Language;
using YotsubaShader.GlslSyntax;
using YotsubaShader.GlslSyntax.Types;
using YotsubaShader.GlslSyntax.Resources;
