// Hexagonal grid (HLSL style): Hexagon cells with a pulsing border, from the hexagonal distance function.
// Hex tiling after the usual hexagonal grid technique, written from scratch.
using YotsubaShader.Language;
using YotsubaShader.HlslSyntax;
using YotsubaShader.HlslSyntax.Types;
using YotsubaShader.HlslSyntax.Resources;
