    {
        float2 i = float2(floor(q.X), floor(q.Y));
        float2 f = q - i;
        f = f * f * (float2(3.0f) - f * 2.0f);
        float a = Hash(i);
        float b = Hash(i + float2(1.0f, 0.0f));
        float c = Hash(i + float2(0.0f, 1.0f));
        float d = Hash(i + float2(1.0f, 1.0f));
        return lerp(lerp(a, b, f.X), lerp(c, d, f.X), f.Y);
    }

