            float glow = (1.0f - smoothstep(0.0f, 0.3f, abs(p.X))) * (0.3f + 0.5f * wave);
            return float4(float3(0.05f, 0.05f, 0.15f) + float3(1.0f, 0.5f, 0.2f) * glow * 0.6f, 1.0f);
        }
