    public vec4<float> Fragment([@builtin_position] vec4<float> fragCoord)
    {
        float aspect = Params.Resolution.X / Params.Resolution.Y;
        vec2<float> uv = vec2f(fragCoord.X / Params.Resolution.X, fragCoord.Y / Params.Resolution.Y);
        vec2<float> p = vec2f((uv.X - 0.5f) * aspect, uv.Y - 0.5f);
        float t = Params.Time;

        vec2<float> q = vec2f(p.X * 3.0f, p.Y * 2.0f - t * 1.2f);
        float n = Fbm(q * 1.5f);
        float shape = 1.0f - length(vec2f(p.X * 1.6f, (uv.Y - 0.1f) * 1.2f));
        float flame = clamp(shape * 1.6f + (n - 0.5f) * 1.2f, 0.0f, 1.0f);
        vec3<float> col = vec3f(flame * 1.6f, flame * flame * 1.1f, flame * flame * flame * 0.8f);
        return vec4f(col, 1.0f);
    }
}

